class AccountSpec : BehaviorSpec({
    given("an account with 100") {
        val account = Account(100)                       // Arrange
        `when`("30 is withdrawn") {
            val ok = account.withdraw(30)                // Act
            then("the balance is 70") {                  // Assert
                ok shouldBe true
                account.balance shouldBe 70
            }
        }
    }
})
